import { View, Text, Pressable, FlatList, StyleSheet } from "react-native";
import { useReducer } from "react";
import { registerRootComponent } from "expo";

function reducer(state, action) {
  // энд бичнэ үү: "add" action — action.name-ийг жагсаалтад нэм
  return state;
}

function App() {
  const [items, dispatch] = useReducer(reducer, []);
  return (
    <View style={styles.s}>
      <Pressable nativeID="add" style={styles.b} onPress={() => dispatch({ type: "add", name: "Гар цаг" })}><Text style={styles.t}>Гар цаг нэмэх</Text></Pressable>
      <FlatList data={items} keyExtractor={(x, i) => String(i)} renderItem={({ item }) => <Text testID="row" style={styles.row}>{item}</Text>} />
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, gap: 12, padding: 24 },
  b: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12, alignItems: "center" }, t: { color: "#fff", fontWeight: "bold" },
  row: { padding: 12, backgroundColor: "#f1f5f9", borderRadius: 8 },
});

registerRootComponent(App);

import { View, Text, Pressable, FlatList, StyleSheet } from "react-native";
import { useReducer } from "react";
import { registerRootComponent } from "expo";

function reducer(state, action) {
  if (action.type === "add") return [...state, action.name];
  return state;
}

function App() {
  const [items, dispatch] = useReducer(reducer, []);
  return (
    <View style={styles.s}>
      <Pressable nativeID="add" style={styles.b} onPress={() => dispatch({ type: "add", name: "Гар цаг" })}><Text style={styles.t}>Гар цаг нэмэх</Text></Pressable>
      <FlatList data={items} keyExtractor={(x, i) => String(i)} renderItem={({ item }) => <Text testID="row" style={styles.row}>{item}</Text>} />
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, gap: 12, padding: 24 },
  b: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12, alignItems: "center" }, t: { color: "#fff", fontWeight: "bold" },
  row: { padding: 12, backgroundColor: "#f1f5f9", borderRadius: 8 },
});

registerRootComponent(App);
